import 'package:flutter/material.dart';
import '../../../core/theme/theme.dart';
import '../models/models.dart';

/// Displays top grounded observations generated by NetworkInsightGenerator.
class NetworkInsightsSection extends StatelessWidget {
  final List<NetworkInsight> insights;

  const NetworkInsightsSection({
    super.key,
    required this.insights,
  });

  @override
  Widget build(BuildContext context) {
    if (insights.isEmpty) {
      return const SizedBox.shrink();
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          children: [
            const Icon(
              Icons.auto_awesome_rounded,
              size: 15.0,
              color: RecallrColors.aiCyanHighlight,
            ),
            const SizedBox(width: 6.0),
            Expanded(
              child: Text(
                'GROUNDED NETWORK INSIGHTS',
                style: RecallrTypography.labelSmall.copyWith(
                  color: RecallrColors.textTertiary,
                  fontSize: 10.5,
                  fontWeight: FontWeight.w700,
                  letterSpacing: 0.8,
                ),
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
              ),
            ),
            const SizedBox(width: 8.0),
            Text(
              '${insights.length} Observations',
              style: RecallrTypography.labelSmall.copyWith(
                color: RecallrColors.textTertiary,
                fontSize: 10.0,
              ),
            ),
          ],
        ),
        const SizedBox(height: 8.0),
        ...insights.map((i) => _buildInsightCard(context, i)),
      ],
    );
  }

  Widget _buildInsightCard(BuildContext context, NetworkInsight insight) {
    final severity = insight.severity;
    final type = insight.type;

    return Container(
      margin: const EdgeInsets.only(bottom: 8.0),
      padding: const EdgeInsets.all(RecallrSpacing.md),
      decoration: BoxDecoration(
        color: RecallrColors.charcoalCard,
        borderRadius: RecallrRadii.radiusMd,
        border: Border.all(
          color: severity == NetworkInsightSeverity.critical
              ? RecallrColors.crimsonAlert.withValues(alpha: 0.35)
              : RecallrColors.borderSubtle,
          width: 1.0,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(type.icon, size: 14.0, color: severity.colorToken),
              const SizedBox(width: 6.0),
              Expanded(
                child: Text(
                  insight.title,
                  style: RecallrTypography.bodyLarge.copyWith(
                    fontWeight: FontWeight.w600,
                    fontSize: 13.0,
                    color: RecallrColors.textPrimary,
                  ),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
              ),
              const SizedBox(width: 4.0),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 6.0, vertical: 2.0),
                decoration: BoxDecoration(
                  color: severity.colorToken.withValues(alpha: 0.12),
                  borderRadius: RecallrRadii.radiusSm,
                  border: Border.all(
                    color: severity.colorToken.withValues(alpha: 0.35),
                    width: 1.0,
                  ),
                ),
                child: Text(
                  severity.badgeLabel,
                  style: RecallrTypography.labelSmall.copyWith(
                    color: severity.colorToken,
                    fontSize: 9.0,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 6.0),
          Text(
            insight.description,
            style: RecallrTypography.bodyMedium.copyWith(
              color: RecallrColors.textSecondary,
              fontSize: 12.0,
              height: 1.4,
            ),
          ),
        ],
      ),
    );
  }
}
